// FoundryServiceServer is the server API for FoundryService service.
// All implementations should embed UnimplementedFoundryServiceServer
// for forward compatibility.
//
// FoundryService is Foundry's API: its plans, connectors and event sources,
// documents and document sets, ontologies, their versions, generations,
// loads, reviews and questions, and the workspace's usage, People
// enrichment and model provider. Every call is of one workspace
// (workspace_id), made for the Actor (actor.proto) the front end that
// authenticated and authorized the caller sends with it.
type FoundryServiceServer interface {
	// Helix Foundry plan
	GetFoundryPlan(context.Context, *GetFoundryPlanRequest) (*FoundryPlanResponse, error)
	CreateFoundryProCheckout(context.Context, *CreateFoundryProCheckoutRequest) (*CreateFoundryProCheckoutResponse, error)
	CancelFoundryPro(context.Context, *CancelFoundryProRequest) (*FoundryPlanResponse, error)
	ResumeFoundryPro(context.Context, *ResumeFoundryProRequest) (*FoundryPlanResponse, error)
	ListFoundryPlans(context.Context, *ListFoundryPlansRequest) (*ListFoundryPlansResponse, error)
	// Helix Foundry connectors
	ListConnectorKinds(context.Context, *ListConnectorKindsRequest) (*ListConnectorKindsResponse, error)
	TestConnector(context.Context, *TestConnectorRequest) (*TestConnectorResponse, error)
	CreateConnector(context.Context, *CreateConnectorRequest) (*ConnectorResponse, error)
	ListConnectors(context.Context, *ListConnectorsRequest) (*ListConnectorsResponse, error)
	GetConnector(context.Context, *GetConnectorRequest) (*ConnectorResponse, error)
	UpdateConnector(context.Context, *UpdateConnectorRequest) (*ConnectorResponse, error)
	DeleteConnector(context.Context, *DeleteConnectorRequest) (*emptypb.Empty, error)
	SyncConnector(context.Context, *SyncConnectorRequest) (*ConnectorSyncResponse, error)
	GetConnectorSync(context.Context, *GetConnectorSyncRequest) (*ConnectorSyncResponse, error)
	ListConnectorSyncs(context.Context, *ListConnectorSyncsRequest) (*ListConnectorSyncsResponse, error)
	// Helix Foundry event sources: connectors of kind events, made, changed and
	// deleted through the connector routes. No route sends pieces.
	CreateFoundryEventSourceToken(context.Context, *CreateFoundryEventSourceTokenRequest) (*CreateFoundryEventSourceTokenResponse, error)
	ListFoundryEventSourceTokens(context.Context, *ListFoundryEventSourceTokensRequest) (*ListFoundryEventSourceTokensResponse, error)
	RevokeFoundryEventSourceToken(context.Context, *RevokeFoundryEventSourceTokenRequest) (*FoundryEventSourceTokenResponse, error)
	ListFoundryEventBatches(context.Context, *ListFoundryEventBatchesRequest) (*ListFoundryEventBatchesResponse, error)
	// Helix Foundry documents and document sets, the workspace's: the Data
	// area.
	ListFoundryDocuments(context.Context, *ListFoundryDocumentsRequest) (*ListFoundryDocumentsResponse, error)
	CreateFoundryDocument(context.Context, *CreateFoundryDocumentRequest) (*CreateFoundryDocumentResponse, error)
	GetFoundryDocument(context.Context, *GetFoundryDocumentRequest) (*FoundryDocumentResponse, error)
	UpdateFoundryDocument(context.Context, *UpdateFoundryDocumentRequest) (*FoundryDocumentResponse, error)
	DeleteFoundryDocument(context.Context, *DeleteFoundryDocumentRequest) (*FoundryDocumentResponse, error)
	GetFoundryDocumentContent(context.Context, *GetFoundryDocumentContentRequest) (*GetFoundryDocumentContentResponse, error)
	GetFoundryDocumentBytes(context.Context, *GetFoundryDocumentBytesRequest) (*GetFoundryDocumentBytesResponse, error)
	CompleteFoundryDocumentUpload(context.Context, *CompleteFoundryDocumentUploadRequest) (*FoundryDocumentReadsResponse, error)
	MoveFoundryDocument(context.Context, *MoveFoundryDocumentRequest) (*FoundryDocumentReadsResponse, error)
	ListFoundryDocumentSets(context.Context, *ListFoundryDocumentSetsRequest) (*ListFoundryDocumentSetsResponse, error)
	CreateFoundryDocumentSet(context.Context, *CreateFoundryDocumentSetRequest) (*FoundryDocumentSetResponse, error)
	UpdateFoundryDocumentSet(context.Context, *UpdateFoundryDocumentSetRequest) (*FoundryDocumentSetResponse, error)
	DeleteFoundryDocumentSet(context.Context, *DeleteFoundryDocumentSetRequest) (*DeleteFoundryDocumentSetResponse, error)
	// The ontology-scoped document and set writes, and the set list, from
	// before documents were the workspace's: aliases of the routes above,
	// with the same workspace semantics, kept for the website still on them
	// until release 2 of workspace documents removes them.
	CreateFoundryOntologyDocument(context.Context, *CreateFoundryOntologyDocumentRequest) (*CreateFoundryOntologyDocumentResponse, error)
	DeleteFoundryOntologyDocument(context.Context, *DeleteFoundryOntologyDocumentRequest) (*FoundryDocumentResponse, error)
	CompleteFoundryOntologyDocumentUpload(context.Context, *CompleteFoundryOntologyDocumentUploadRequest) (*FoundryDocumentReadsResponse, error)
	MoveFoundryOntologyDocument(context.Context, *MoveFoundryOntologyDocumentRequest) (*FoundryDocumentReadsResponse, error)
	ListFoundryOntologyDocumentSets(context.Context, *ListFoundryOntologyDocumentSetsRequest) (*ListFoundryDocumentSetsResponse, error)
	CreateFoundryOntologyDocumentSet(context.Context, *CreateFoundryOntologyDocumentSetRequest) (*FoundryDocumentSetResponse, error)
	UpdateFoundryOntologyDocumentSet(context.Context, *UpdateFoundryOntologyDocumentSetRequest) (*FoundryDocumentSetResponse, error)
	DeleteFoundryOntologyDocumentSet(context.Context, *DeleteFoundryOntologyDocumentSetRequest) (*DeleteFoundryDocumentSetResponse, error)
	GetFoundryDataLayout(context.Context, *GetFoundryDataLayoutRequest) (*FoundryDataLayoutResponse, error)
	PutFoundryDataLayout(context.Context, *PutFoundryDataLayoutRequest) (*FoundryDataLayoutResponse, error)
	// Helix Foundry ontologies, each bound to one tenant database. Deleting one
	// leaves its database as it is.
	CreateFoundryOntology(context.Context, *CreateFoundryOntologyRequest) (*FoundryOntologyResponse, error)
	ListFoundryOntologies(context.Context, *ListFoundryOntologiesRequest) (*ListFoundryOntologiesResponse, error)
	GetFoundryOntology(context.Context, *GetFoundryOntologyRequest) (*FoundryOntologyResponse, error)
	DeleteFoundryOntology(context.Context, *DeleteFoundryOntologyRequest) (*FoundryOntologyResponse, error)
	UpdateFoundryOntology(context.Context, *UpdateFoundryOntologyRequest) (*FoundryOntologyResponse, error)
	GetCurrentOntologyVersion(context.Context, *GetCurrentOntologyVersionRequest) (*OntologyVersionResponse, error)
	ListOntologyVersions(context.Context, *ListOntologyVersionsRequest) (*ListOntologyVersionsResponse, error)
	GetOntologyVersion(context.Context, *GetOntologyVersionRequest) (*OntologyVersionResponse, error)
	CreateOntologyVersion(context.Context, *CreateOntologyVersionRequest) (*OntologyVersionResponse, error)
	SetCurrentOntologyVersion(context.Context, *SetCurrentOntologyVersionRequest) (*OntologyVersionResponse, error)
	ReviseOntologyVersion(context.Context, *ReviseOntologyVersionRequest) (*OntologyGenerationResponse, error)
	GenerateOntology(context.Context, *GenerateOntologyRequest) (*OntologyGenerationResponse, error)
	GetOntologyGeneration(context.Context, *GetOntologyGenerationRequest) (*OntologyGenerationResponse, error)
	ListOntologyGenerations(context.Context, *ListOntologyGenerationsRequest) (*ListOntologyGenerationsResponse, error)
	SettleFoundryReview(context.Context, *SettleFoundryReviewRequest) (*FoundryReviewDecisionResponse, error)
	ListFoundryReviewDecisions(context.Context, *ListFoundryReviewDecisionsRequest) (*ListFoundryReviewDecisionsResponse, error)
	DeleteFoundryReviewDecision(context.Context, *DeleteFoundryReviewDecisionRequest) (*DeleteFoundryReviewDecisionResponse, error)
	// An ontology's documents, read only: what its current load holds and
	// what its reading version's scope holds, each with its extraction there.
	ListFoundryOntologyDocuments(context.Context, *ListFoundryOntologyDocumentsRequest) (*ListFoundryDocumentsResponse, error)
	GetFoundryOntologyDocument(context.Context, *GetFoundryOntologyDocumentRequest) (*FoundryDocumentResponse, error)
	CreateFoundryLoad(context.Context, *CreateFoundryLoadRequest) (*FoundryLoadResponse, error)
	ListFoundryLoads(context.Context, *ListFoundryLoadsRequest) (*ListFoundryLoadsResponse, error)
	GetFoundryLoad(context.Context, *GetFoundryLoadRequest) (*FoundryLoadResponse, error)
	SetCurrentFoundryLoad(context.Context, *SetCurrentFoundryLoadRequest) (*FoundryLoadResponse, error)
	DeleteFoundryLoad(context.Context, *DeleteFoundryLoadRequest) (*FoundryLoadResponse, error)
	ReadFoundryGraph(context.Context, *ReadFoundryGraphRequest) (*ReadFoundryGraphResponse, error)
	AskFoundryQuestion(context.Context, *AskFoundryQuestionRequest) (*FoundryQuestionResponse, error)
	GetFoundryQuestion(context.Context, *GetFoundryQuestionRequest) (*FoundryQuestionResponse, error)
	ListFoundryQuestions(context.Context, *ListFoundryQuestionsRequest) (*ListFoundryQuestionsResponse, error)
	ListFoundryQuestionEvents(context.Context, *ListFoundryQuestionEventsRequest) (*ListFoundryQuestionEventsResponse, error)
	CancelFoundryQuestion(context.Context, *CancelFoundryQuestionRequest) (*FoundryQuestionResponse, error)
	StopFoundryLoadEnrichment(context.Context, *StopFoundryLoadEnrichmentRequest) (*FoundryLoadResponse, error)
	// Helix Foundry usage: the workspace's AI spend this month, by task
	//
	// The UTC calendar month's spend of loads, of API sources' extraction no
	// person started, and of questions, each with its cap: the sums the caps
	// check. Spend on the workspace's own model key counts, as Helix's monthly
	// caps count it. Any member may read it.
	GetFoundryUsage(context.Context, *GetFoundryUsageRequest) (*FoundryUsageResponse, error)
	// Helix Foundry People enrichment
	GetFoundryEnrichment(context.Context, *GetFoundryEnrichmentRequest) (*FoundryEnrichmentResponse, error)
	UpdateFoundryEnrichment(context.Context, *UpdateFoundryEnrichmentRequest) (*FoundryEnrichmentResponse, error)
	// Helix Foundry model providers
	GetFoundryAI(context.Context, *GetFoundryAIRequest) (*FoundryAIResponse, error)
	UpdateFoundryAI(context.Context, *UpdateFoundryAIRequest) (*FoundryAIResponse, error)
}

